mapper.sql:
SELECT eo.ID AS ID, eo.create_user_id AS createUserId, eo.create_user_name AS createUserName, eo.create_time AS createTime, eo.update_user_id AS updateUserId, eo.update_user_name AS updateUserName, eo.update_time AS updateTime, eo.VERSION AS VERSION, eo.is_deleted AS isDeleted, eo.invalid_status AS invalidStatus, eo.code AS code, eo.exhibition_title AS exhibitionTitle, eo.approve_status AS approveStatus, eo.sales_org_id AS salesOrgId, eo.sales_dept_id AS salesDeptId, eo.seller_id AS sellerId, eo.seller_name AS sellerName, eo.recipient_user_id AS recipientUserId, eo.recipient_user_name AS recipientUserName, eo.is_collect_shipping_fee AS isCollectShippingFee, eo.warehouse_id AS warehouseId, eo.warehouse_org_id AS warehouseOrgId, eo.bank_service_fee AS bankServiceFee, eo.shipping_fee AS shippingFee, eo.customer_id AS customerId, eo.receiver_name AS receiverName, eo.tel_number AS telNumber, eo.receive_address AS receiveAddress, eo.delivery_mode AS deliveryMode, eo.currency AS currency, eo.currency_symbol AS currencySymbol, eo.is_tax AS isTax, eo.address_type AS addressType, eo.sales_org_name AS salesOrgName, eo.warehouse_org_name AS warehouseOrgName, eo.receive_address_id AS receiveAddressId, eo.approve_user_name AS approveUserName, eo.receive_condition AS receiveCondition, eo.receive_account AS receiveAccount, eo.receive_amount AS receiveAmount, eo.receive_date AS receiveDate, eo.receive_method AS receiveMethod, eo.remark AS remark, eo.bill_date AS billDate, eo.trade_term AS tradeTerm, eo.approve_time AS approveTime, eo.discount_amount AS discountAmount, eo.all_amount_lc AS allAmountLc, eo.country_id AS countryId, eo.country_name AS countryName, eo.partition_id AS partitionId, fdp.code as partitionCode, fdp.name as partitionName eod.ID AS detailId, eod.main_id AS mainId, eod.source_detail_id AS sourceDetailId, eod.sku_id AS skuId, eod.sku_no AS skuNo, eod.product_name AS productName, eod.qty AS qty, eod.price AS price, eod.tax_rate AS taxRate, eod.amount AS amount, eod.currency AS currency, eod.currency_symbol AS currencySymbol, eod.is_gift AS isGift, eod.remark AS detailRemark, eod.purchase_price AS purchasePrice, eod.sale_cost AS saleCost, eod.sale_profit AS saleProfit, eod.sale_profit_rate AS saleProfitRate, eod.tax_amount AS taxAmount, eod.amount_local_currency AS amountLocalCurrency, eod.all_amount_local_currency AS allAmountLocalCurrency, eod.discount_amount AS discountAmount, eod.tax_amount_before AS taxAmountBefore, eod.exchange_rate AS exchangeRate, eod.tax AS tax, eod.bom_version AS bomVersion, eod.cost_source AS costSource, eod.tax_price AS taxPrice FROM exhibition_order AS eo LEFT JOIN exhibition_order_detail AS eod ON eo.ID = eod.main_id AND eod.is_deleted = FALSE left join foreign_dict_partition fdp on fdp.id = eo.partition_id and fdp.is_deleted = false WHERE ${params.sqlMap.default} and eo.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
eo.create_time desc

mapper.select:
SELECT approve_status AS tabFlag, count(*) AS count FROM exhibition_order WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status

select ssd.sku_id , sum(ssd.return_qty) as freezeQty from exhibition_order ssi inner join exhibition_order_detail ssd on ssi.id = ssd.main_id and ssd.is_deleted = false where ssi.is_deleted = false and ssi.approve_status !='approve'
and ssi.id != #{params.childId}
and ssd.sku_no in
#{item}
GROUP BY ssd.sku_id
